WITH not_flagged AS (SELECT s.* FROM products s WHERE EXISTS (SELECT 1 FROM inventory ch WHERE ch.product_id = s.id AND ch.last_restock < s.launch_date)) SELECT s.id, s.product_name, s.category, s.brand, s.price, s.cost, s.stock_qty, s.launch_date, s.supplier_id, CASE WHEN brand RLIKE '^(Initech|Umbrella)$' THEN 'OTHER_ZONE' WHEN brand RLIKE '^(Acme|Globex)$' THEN 'GROUP_B' ELSE 'CORE' END AS brand_zone, (SELECT MIN(x.stock_qty) FROM products x WHERE x.supplier_id = s.supplier_id) AS min_product_stock_qty FROM not_flagged s ORDER BY min_product_stock_qty DESC NULLS FIRST, brand_zone DESC;
